// --- provided deterministic challenge transform (stand-in for SHA-256 + base64url).
// Do NOT replace with real crypto; this is a fixed function so the sandbox is deterministic.
function deriveChallenge(verifier) {
  let h = 2166136261; // FNV-1a-ish fold
  for (let i = 0; i < verifier.length; i++) {
    h ^= verifier.charCodeAt(i);
    h = (h * 16777619) >>> 0;
  }
  // emit as fixed-width unsigned hex, prefixed like a base64url-ish token
  return 'ch_' + h.toString(16).padStart(8, '0');
}

// At /authorize the client computed and the server stored this challenge:
const genuineVerifier = 'dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk';
const storedChallenge = deriveChallenge(genuineVerifier);

function tokenEndpoint(presentedVerifier) {
  return deriveChallenge(presentedVerifier) === storedChallenge ? 'ACCEPT' : 'REJECT';
}

// /token call 1: the genuine client presents the real verifier.
console.log('genuine: ' + tokenEndpoint(genuineVerifier));
// /token call 2: an attacker who intercepted the code guesses a verifier.
console.log('attacker: ' + tokenEndpoint('attacker-guessed-verifier-value-1234567890'));
